#[derive(Debug, Clone, PartialEq)]
pub struct VoxelCells {
    pub x_size: u8,
    pub y_size: u8,
    pub z_size: u8,
    pub storage: Vec<u8>,
}
impl VoxelCells {
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let f_x_size =
            (|| -> Result<_> { Ok(read_u8(r)?) })().map_err(|e| e.at("VoxelCells.x_size"))?;
        let f_y_size =
            (|| -> Result<_> { Ok(read_u8(r)?) })().map_err(|e| e.at("VoxelCells.y_size"))?;
        let f_z_size =
            (|| -> Result<_> { Ok(read_u8(r)?) })().map_err(|e| e.at("VoxelCells.z_size"))?;
        let f_storage = (|| -> Result<_> {
            Ok({
                let n = to_len(read_varint(r)?)?;
                let mut v = Vec::with_capacity(cap(n, r));
                for _ in 0..n {
                    v.push(read_u8(r)?);
                }
                v
            })
        })()
        .map_err(|e| e.at("VoxelCells.storage"))?;
        Ok(Self {
            x_size: f_x_size,
            y_size: f_y_size,
            z_size: f_z_size,
            storage: f_storage,
        })
    }
    pub fn write(&self, w: &mut BytesMut) {
        write_u8(w, self.x_size);
        write_u8(w, self.y_size);
        write_u8(w, self.z_size);
        write_varint(w, self.storage.len() as u32);
        for x0 in self.storage.iter() {
            write_u8(w, *x0);
        }
    }
}

